#!/bin/sh
# Ghostly installer for Alpine on iPhone. Generated by scripts/build-boot.sh.
set -eu

BASE_URL='https://raw.githubusercontent.com/Mora140/ghosty-releases/phone'
# Content-addressed, so a cached install.sh never pairs with a different binary.
BINARY='ghostly-boot-d71f235da4df'
SHA256='d71f235da4df3715e72c4dcc55c75874582aa78deae72fe071aee51a2aa9f332'

DIR="$HOME/.ghostly/bin"
TMP=""
trap '[ -z "$TMP" ] || rm -f "$TMP"' EXIT

fail() {
  echo "$1"
  exit 1
}

if [ ! -e /etc/ssl/certs/ca-certificates.crt ] && [ ! -e /etc/ssl/cert.pem ] \
  && command -v apk >/dev/null 2>&1; then
  echo "Preparing secure connections..."
  apk add --no-cache ca-certificates >/dev/null 2>&1 || true
fi

command -v wget >/dev/null 2>&1 \
  || fail "This environment cannot download files. Open a fresh Alpine environment and run the command again."

mkdir -p "$DIR" 2>/dev/null && chmod 700 "$DIR" 2>/dev/null \
  || fail "Ghostly could not create its folder. Make sure the Alpine environment has free space and run the command again."

( : < /dev/tty ) 2>/dev/null \
  || fail "This must be run in a terminal window. Open the terminal app and run the command again."

TMP="$DIR/ghostly-boot.part.$$"
echo "Downloading Ghostly installer..."
wget -q -O "$TMP" "$BASE_URL/$BINARY" \
  || fail "The download did not arrive. Check your internet connection and run the command again."

echo "Checking the download..."
if ! echo "$SHA256  $TMP" | sha256sum -c - >/dev/null 2>&1; then
  rm -f "$TMP"
  fail "The download did not arrive intact. Check your internet connection and run the command again."
fi

chmod 700 "$TMP" && mv -f "$TMP" "$DIR/ghostly-boot" \
  || fail "Ghostly could not save the installer. Make sure the Alpine environment has free space and run the command again."
TMP=""

echo "Starting Ghostly installer..."
exec "$DIR/ghostly-boot" "$@" < /dev/tty
